#include <unordered_map>

#include <opencv2/core/persistence.hpp>

#include "rmvlpara/camera/mv_camera.h"

namespace rm::para
{


bool MvCameraParam::load(const std::string &path)
{
    cv::FileStorage fs(path, cv::FileStorage::READ);
    if (!fs.isOpened())
        return false;
    cv::FileNode node;

    node = fs["exposure"];
    node.isNone() ? void(0) : (node >> exposure);
    node = fs["gamma"];
    node.isNone() ? void(0) : (node >> gamma);
    node = fs["contrast"];
    node.isNone() ? void(0) : (node >> contrast);
    node = fs["saturation"];
    node.isNone() ? void(0) : (node >> saturation);
    node = fs["sharpness"];
    node.isNone() ? void(0) : (node >> sharpness);
    node = fs["gain"];
    node.isNone() ? void(0) : (node >> gain);
    node = fs["b_gain"];
    node.isNone() ? void(0) : (node >> b_gain);
    node = fs["g_gain"];
    node.isNone() ? void(0) : (node >> g_gain);
    node = fs["r_gain"];
    node.isNone() ? void(0) : (node >> r_gain);
    node = fs["grab_mode"];
    node.isNone() ? void(0) : (node >> grab_mode);
    node = fs["retrieve_mode"];
    node.isNone() ? void(0) : (node >> retrieve_mode);
    node = fs["auto_exposure"];
    node.isNone() ? void(0) : (node >> auto_exposure);
    node = fs["auto_wb"];
    node.isNone() ? void(0) : (node >> auto_wb);
    node = fs["lut_vec"];
    node.isNone() ? void(0) : (node >> lut_vec);
    node = fs["serial_number"];
    node.isNone() ? void(0) : (node >> serial_number);

    return true;
}

} // rm::para
